package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.ErrorCode;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import org.springframework.beans.factory.ListableBeanFactory;import org.springframework.stereotype.Component;import org.springframework.util.function.ThrowingSupplier;
/** Deployment availability only. Never implies audit or target/source permissions. */
@Component public final class BusinessAuditFeatureAvailability{
 private final EnterpriseAccess access;private final ListableBeanFactory beans;private final PermissionSchema json;private final BusinessAuditSchema schema;
 public BusinessAuditFeatureAvailability(EnterpriseAccess access,ListableBeanFactory beans,PermissionSchema json)throws Exception{this.access=access;this.beans=beans;this.json=json;schema=new BusinessAuditSchema();}
 JsonNode read(ApplicationSessionIdentity.Verified subject,String context){return access.execute(subject,a->ThrowingSupplier.of(()->{if(!context.equals(a.context().context_revision()))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);boolean enabled=beans.getBeanNamesForType(BusinessAuditController.class,false,false).length>0;var value=json.object().put("schema_version","1.0.0").put("coverage_scope","DOCUMENT_SAVE_AUDIT").put("scope_mode","PROJECT_REQUIRED");value.set("current_context",json.tree(a.context()));value.set("features",json.object().put("business_audit",enabled));value.putArray("supported_actions").add(BusinessAuditDocumentSavedAuthority.ACTION);if(enabled){var p=beans.getBean(BusinessAuditPolicy.class);value.put("maximum_page_size",p.maximumPageSize()).put("maximum_window_seconds",p.maximumWindowSeconds()).put("maximum_response_bytes",p.maximumResponseBytes());}else value.putNull("maximum_page_size").putNull("maximum_window_seconds").putNull("maximum_response_bytes");return schema.validate("Availability",value);}).get());}
}
